<script setup lang="ts">
import { computed, ref } from 'vue'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import { FileCheck2, LoaderCircle, Plus, RefreshCw, Send, Sparkles, ThumbsDown, ThumbsUp } from 'lucide-vue-next'
import BaseButton from '@/components/ui/BaseButton.vue'
import FormField from '@/components/ui/FormField.vue'
import PanelCard from '@/components/ui/PanelCard.vue'
import StatePanel from '@/components/ui/StatePanel.vue'
import StatusBadge from '@/components/ui/StatusBadge.vue'
import AppModal from '@/components/ui/AppModal.vue'
import { api } from '@/services/api'
import { getApiErrorMessage } from '@/services/api/http'
import { useAuthStore } from '@/stores/auth'
import { useToastStore } from '@/stores/toast'
import { formatDate, titleOf } from '@/utils/format'
import type { FollowUpRecord, RecommendationRecord } from '@/types/api'

const auth = useAuthStore()
const toast = useToastStore()
const qc = useQueryClient()
const canManage = computed(() => ['ADMIN_SPI', 'PIMPINAN_SPI'].includes(auth.role || ''))
const modalOpen = ref(false)
const taskModalOpen = ref(false)
const selectedMemoId = ref('')
const taskRecommendation = ref<RecommendationRecord | null>(null)
const assignment = ref({ assigneeId: '', dueDate: '' })
const dispositionText = ref('')
const manualForm = ref({ title: '', description: '', action: '', priority: 'MEDIUM', assigneeId: '', dueDate: '' })
const draft = ref({ memoNumber: '', recipient: '', cc: '', fromUnit: '', subject: '', memoDate: new Date().toISOString().slice(0, 10), reportId: '', reportReviewId: '' })

const memosQuery = useQuery({ queryKey: ['memos'], queryFn: () => api.memos({ page: 1, limit: 100 }) })
const reportsQuery = useQuery({ queryKey: ['memo-eligible-reports'], queryFn: () => api.reports({ page: 1, limit: 100 }), enabled: canManage })
const assigneesQuery = useQuery({ queryKey: ['task-assignees'], queryFn: () => api.taskAssignees({ page: 1, limit: 100 }), enabled: canManage })
const memoQuery = useQuery({ queryKey: computed(() => ['memo', selectedMemoId.value]), queryFn: () => api.memo(selectedMemoId.value), enabled: computed(() => !!selectedMemoId.value) })
const dispositionReviewQuery = useQuery({ queryKey: computed(() => ['memo-disposition-review', selectedMemoId.value]), queryFn: () => api.memoDispositionReview(selectedMemoId.value), enabled: computed(() => !!memoQuery.data.value?.dispositionVersionId), refetchInterval: 5000 })
const followUpsQuery = useQuery({ queryKey: computed(() => ['memo-follow-ups', memoQuery.data.value?.reportId]), queryFn: () => api.followUps(String(memoQuery.data.value?.reportId)), enabled: computed(() => !!memoQuery.data.value?.reportId) })
const reports = computed(() => reportsQuery.data.value?.items || [])
const eligibleReports = computed(() => reports.value.filter((report) => report.latestReview?.status === 'COMPLETED'))
const memos = computed(() => memosQuery.data.value?.items || [])
const followUps = computed<FollowUpRecord[]>(() => followUpsQuery.data.value?.items || [])
const recommendations = computed<RecommendationRecord[]>(() => dispositionReviewQuery.data.value?.recommendations || [])
const selectedReport = computed(() => reports.value.find((report) => report._id === draft.value.reportId))
const reviewAgeMinutes = computed(() => { const createdAt = dispositionReviewQuery.data.value?.review?.createdAt; return createdAt ? (Date.now() - new Date(createdAt).getTime()) / 60000 : 0 })

const createMutation = useMutation({ mutationFn: api.createMemo, onSuccess: async (memo) => { await qc.invalidateQueries({ queryKey: ['memos'] }); selectedMemoId.value = memo._id; modalOpen.value = false; draft.value = { memoNumber: '', recipient: '', cc: '', fromUnit: '', subject: '', memoDate: new Date().toISOString().slice(0, 10), reportId: '', reportReviewId: '' }; toast.show({ kind: 'success', title: 'Memo berhasil dibuat' }) }, onError: (error) => toast.show({ kind: 'error', title: 'Memo tidak dapat dibuat', description: getApiErrorMessage(error) }) })
const statusMutation = useMutation({ mutationFn: ({ id, status }: { id: string; status: 'SENT_TO_SHEYLA' | 'SENT_TO_DIRECTOR' }) => api.updateMemoStatus(id, status), onSuccess: async () => { await refreshMemos(); toast.show({ kind: 'success', title: 'Status memo diperbarui' }) }, onError: (error) => toast.show({ kind: 'error', title: 'Status memo tidak berubah', description: getApiErrorMessage(error) }) })
const dispositionMutation = useMutation({ mutationFn: () => api.submitMemoDisposition(selectedMemoId.value, dispositionText.value.trim()), onSuccess: async () => { dispositionText.value = ''; await refreshMemos(); toast.show({ kind: 'success', title: 'Teks disposisi disimpan', description: 'Teks akan dianalisis bersama versi laporan yang dikirim ke Direktur.' }) }, onError: (error) => toast.show({ kind: 'error', title: 'Teks disposisi tidak dapat disimpan', description: getApiErrorMessage(error) }) })
const reviewMutation = useMutation({ mutationFn: api.startMemoDispositionReview, onSuccess: async () => { await dispositionReviewQuery.refetch(); toast.show({ kind: 'success', title: 'Review disposisi AI dimulai' }) }, onError: (error) => toast.show({ kind: 'error', title: 'Review AI belum dapat dimulai', description: getApiErrorMessage(error) }) })
const decisionMutation = useMutation({ mutationFn: ({ recommendation, decision }: { recommendation: RecommendationRecord; decision: 'approve' | 'reject' }) => api.decideRecommendation(String(memoQuery.data.value?.reportId), String(dispositionReviewQuery.data.value?.review?._id), recommendation._id, decision), onSuccess: async () => { await dispositionReviewQuery.refetch(); toast.show({ kind: 'success', title: 'Keputusan rekomendasi tersimpan' }) }, onError: (error) => toast.show({ kind: 'error', title: 'Keputusan rekomendasi gagal', description: getApiErrorMessage(error) }) })
const verifyRecommendationMutation = useMutation({ mutationFn: (recommendation: RecommendationRecord) => api.updateRecommendation(String(memoQuery.data.value?.reportId), String(dispositionReviewQuery.data.value?.review?._id), recommendation._id, { verificationStatus: 'SUPPORTED' }), onSuccess: async () => { await dispositionReviewQuery.refetch(); toast.show({ kind: 'success', title: 'Sumber rekomendasi dikonfirmasi untuk ditinjau' }) }, onError: (error) => toast.show({ kind: 'error', title: 'Verifikasi rekomendasi gagal', description: getApiErrorMessage(error) }) })
const convertMutation = useMutation({ mutationFn: ({ recommendation, assigneeId, dueDate }: { recommendation: RecommendationRecord; assigneeId: string; dueDate: string }) => api.createFollowUp(String(memoQuery.data.value?.reportId), recommendation._id, assigneeId || undefined, dueDate ? new Date(dueDate).toISOString() : undefined), onSuccess: async () => { taskModalOpen.value = false; taskRecommendation.value = null; assignment.value = { assigneeId: '', dueDate: '' }; await followUpsQuery.refetch(); toast.show({ kind: 'success', title: 'Rekomendasi masuk ke tindak lanjut' }) }, onError: (error) => toast.show({ kind: 'error', title: 'Tindak lanjut tidak dapat dibuat', description: getApiErrorMessage(error) }) })
const manualMutation = useMutation({ mutationFn: () => api.createManualFollowUpFromMemo(selectedMemoId.value, { ...manualForm.value, dueDate: manualForm.value.dueDate ? new Date(manualForm.value.dueDate).toISOString() : undefined }), onSuccess: async () => { await followUpsQuery.refetch(); manualForm.value = { title: '', description: '', action: '', priority: 'MEDIUM', assigneeId: '', dueDate: '' }; toast.show({ kind: 'success', title: 'Tindak lanjut manual ditambahkan' }) }, onError: (error) => toast.show({ kind: 'error', title: 'Tindak lanjut manual gagal dibuat', description: getApiErrorMessage(error) }) })

async function refreshMemos() { await Promise.all([qc.invalidateQueries({ queryKey: ['memos'] }), memoQuery.refetch(), dispositionReviewQuery.refetch(), followUpsQuery.refetch()]) }
function selectReport() { draft.value.reportReviewId = selectedReport.value?.latestReview?._id || '' }
function createMemo() { if (!draft.value.reportReviewId) return; createMutation.mutate({ ...draft.value, memoDate: new Date(`${draft.value.memoDate}T00:00:00+07:00`).toISOString() }) }
function moveStatus(status: 'SENT_TO_SHEYLA' | 'SENT_TO_DIRECTOR') { statusMutation.mutate({ id: selectedMemoId.value, status }) }
function openTaskModal(recommendation: RecommendationRecord) { taskRecommendation.value = recommendation; taskModalOpen.value = true }
function createTaskFromRecommendation() { if (taskRecommendation.value) convertMutation.mutate({ recommendation: taskRecommendation.value, ...assignment.value }) }
function memoStatusLabel(status?: string) { return ({ DRAFT: 'Draf', SENT_TO_SHEYLA: 'Diserahkan ke Sheyla', SENT_TO_DIRECTOR: 'Dikirim ke Direktur', DISPOSITION_RECEIVED: 'Disposisi diterima' } as Record<string, string>)[status || ''] || status || '—' }
</script>

<template>
  <main class="space-y-5">
    <header class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-[10px] font-bold uppercase tracking-[.18em] text-blue-600">Administrasi dan monitoring</p><h1 class="mt-1 text-2xl font-bold tracking-tight text-navy-950">Memo & Tindak Lanjut</h1><p class="mt-1 text-sm text-slate-500">Catat perjalanan memo, disposisi Direktur, review AI, dan rencana tindak lanjut.</p></div><BaseButton v-if="canManage" @click="modalOpen=true"><Plus class="size-4" />Buat memo</BaseButton></header>
    <div class="grid gap-3 sm:grid-cols-3"><PanelCard title="Memo" :description="`${memos.length} memo tercatat`"><p class="text-2xl font-bold text-navy-950">{{ memos.length }}</p></PanelCard><PanelCard title="Disposisi diterima" description="Memo menunggu/selesai ditinjau ulang"><p class="text-2xl font-bold text-navy-950">{{ memos.filter(m => m.status === 'DISPOSITION_RECEIVED').length }}</p></PanelCard><PanelCard title="Tindak lanjut aktif" description="Tugas yang belum selesai"><p class="text-2xl font-bold text-navy-950">{{ followUps.filter(f => f.status !== 'COMPLETED').length }}</p></PanelCard></div>
    <PanelCard title="Daftar memo" description="Memo hanya dapat dibuat untuk laporan yang sudah memiliki hasil AI review selesai.">
      <StatePanel v-if="memosQuery.isPending.value" state="loading" title="Memuat memo" />
      <StatePanel v-else-if="memosQuery.isError.value" state="error" title="Memo belum dapat dimuat" :description="getApiErrorMessage(memosQuery.error.value)" @retry="memosQuery.refetch()" />
      <StatePanel v-else-if="!memos.length" state="empty" title="Belum ada memo" description="Buat memo setelah laporan selesai direview AI." />
      <div v-else class="overflow-x-auto"><table class="w-full min-w-[760px] text-left"><thead><tr class="border-b border-slate-100 text-[10px] font-bold uppercase tracking-wide text-slate-400"><th class="px-3 py-3">Nomor / tanggal</th><th class="px-3 py-3">Perihal</th><th class="px-3 py-3">Kepada</th><th class="px-3 py-3">Unit asal</th><th class="px-3 py-3">Status</th><th class="px-3 py-3"></th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="memo in memos" :key="memo._id" class="text-xs text-slate-600"><td class="px-3 py-4"><p class="font-semibold text-slate-800">{{ memo.memoNumber }}</p><p class="mt-1 text-[10px] text-slate-400">{{ formatDate(memo.memoDate) }}</p></td><td class="px-3 py-4"><p class="font-semibold text-slate-800">{{ memo.subject }}</p><p class="mt-1 text-[10px] text-slate-400">{{ memo.reportTitle }}</p></td><td class="px-3 py-4">{{ memo.recipient }}</td><td class="px-3 py-4">{{ memo.fromUnit }}</td><td class="px-3 py-4"><StatusBadge :status="memo.status" /> <span class="ml-1 text-[10px] text-slate-500">{{ memoStatusLabel(memo.status) }}</span></td><td class="px-3 py-4 text-right"><BaseButton size="sm" variant="secondary" @click="selectedMemoId=memo._id">Detail</BaseButton></td></tr></tbody></table></div>
    </PanelCard>

    <section v-if="selectedMemoId" class="space-y-4">
      <PanelCard title="Rincian proses memo" :description="memoQuery.data.value?.subject || 'Memuat data memo…'">
        <template #actions><BaseButton size="sm" variant="secondary" :disabled="memoQuery.isFetching.value" @click="refreshMemos()"><RefreshCw class="size-3.5" :class="memoQuery.isFetching.value && 'animate-spin'" />Muat ulang</BaseButton><button class="ml-2 text-xs text-slate-400 hover:text-slate-700" @click="selectedMemoId=''">Tutup</button></template>
        <StatePanel v-if="memoQuery.isPending.value" state="loading" title="Memuat detail memo" />
        <div v-else-if="memoQuery.data.value" class="space-y-5">
          <div class="grid gap-3 rounded-xl bg-slate-50 p-4 text-xs sm:grid-cols-2 lg:grid-cols-3"><p><span class="text-slate-400">Nomor memo</span><br /><b>{{ memoQuery.data.value.memoNumber }}</b></p><p><span class="text-slate-400">Kepada</span><br /><b>{{ memoQuery.data.value.recipient }}</b></p><p><span class="text-slate-400">Tembusan</span><br /><b>{{ memoQuery.data.value.cc?.join(', ') || '—' }}</b></p><p><span class="text-slate-400">Dari unit</span><br /><b>{{ memoQuery.data.value.fromUnit }}</b></p><p><span class="text-slate-400">Tanggal memo</span><br /><b>{{ formatDate(memoQuery.data.value.memoDate) }}</b></p><p><span class="text-slate-400">Status</span><br /><b>{{ memoStatusLabel(memoQuery.data.value.status) }}</b></p></div>
          <div v-if="canManage" class="flex flex-wrap gap-2"><BaseButton v-if="memoQuery.data.value.status==='DRAFT'" size="sm" :disabled="statusMutation.isPending.value" @click="moveStatus('SENT_TO_SHEYLA')"><Send class="size-3.5" />Tandai diserahkan ke Sheyla</BaseButton><BaseButton v-if="memoQuery.data.value.status==='SENT_TO_SHEYLA'" size="sm" :disabled="statusMutation.isPending.value" @click="moveStatus('SENT_TO_DIRECTOR')"><Send class="size-3.5" />Tandai dikirim ke Direktur</BaseButton></div>
          <div v-if="memoQuery.data.value.status==='SENT_TO_DIRECTOR' && canManage" class="rounded-xl border border-dashed border-blue-200 bg-blue-50/40 p-4"><h3 class="text-xs font-bold text-slate-800">Input isi disposisi / arahan Direktur</h3><p class="mt-1 text-[11px] text-slate-500">Laporan yang dikirim ke Direktur tetap menjadi dokumen yang dianalisis. Masukkan teks arahan secara manual agar terbaca akurat oleh AI.</p><div class="mt-3 space-y-3"><textarea v-model="dispositionText" class="field-input min-h-32 resize-y" maxlength="10000" placeholder="Contoh: Setujui tindak lanjut, koordinasikan dengan unit terkait, dan laporkan hasilnya paling lambat ..." /><div class="flex flex-wrap items-center justify-between gap-3"><span class="text-[10px] text-slate-400">{{ dispositionText.length }}/10000 karakter</span><BaseButton size="sm" :disabled="dispositionText.trim().length < 5 || dispositionMutation.isPending.value" @click="dispositionMutation.mutate()"><LoaderCircle v-if="dispositionMutation.isPending.value" class="size-3.5 animate-spin" /><FileCheck2 v-else class="size-3.5" />Simpan teks disposisi</BaseButton></div></div></div>
          <div v-if="memoQuery.data.value.dispositionVersionId" class="rounded-xl border border-slate-100 p-4"><div class="flex flex-wrap items-center justify-between gap-3"><div><h3 class="text-xs font-bold text-slate-800">Review AI atas laporan dan disposisi</h3><p class="mt-1 text-[11px] text-slate-500">Status teks disposisi: {{ memoQuery.data.value.dispositionVersion?.status === 'EXTRACTED' ? 'Siap dianalisis' : memoQuery.data.value.dispositionVersion?.status }}</p></div><BaseButton v-if="canManage && memoQuery.data.value.dispositionVersion?.status==='EXTRACTED' && dispositionReviewQuery.data.value?.review?.status!=='COMPLETED' && dispositionReviewQuery.data.value?.review?.status!=='PROCESSING'" size="sm" :disabled="reviewMutation.isPending.value" @click="reviewMutation.mutate(selectedMemoId)"><LoaderCircle v-if="reviewMutation.isPending.value" class="size-3.5 animate-spin" /><Sparkles v-else class="size-3.5" />Review laporan + disposisi</BaseButton><BaseButton v-if="canManage && dispositionReviewQuery.data.value?.review?.status==='PROCESSING' && reviewAgeMinutes>=8" size="sm" variant="secondary" :disabled="reviewMutation.isPending.value" @click="reviewMutation.mutate(selectedMemoId)"><LoaderCircle v-if="reviewMutation.isPending.value" class="size-3.5 animate-spin" /><RefreshCw v-else class="size-3.5" />Mulai ulang review yang macet</BaseButton></div>
            <div v-if="memoQuery.data.value.dispositionVersion?.data?.extractedText" class="mt-4 rounded-lg border border-blue-100 bg-blue-50/50 p-3"><p class="text-[10px] font-bold text-blue-800">Teks disposisi yang dianalisis</p><p class="mt-1 whitespace-pre-wrap text-xs leading-5 text-slate-700">{{ memoQuery.data.value.dispositionVersion.data.extractedText }}</p></div>
            <StatePanel v-if="memoQuery.data.value.dispositionVersion?.status==='PROCESSING'" state="loading" title="Menyiapkan disposisi" description="Teks disposisi sedang diproses." />
            <StatePanel v-else-if="dispositionReviewQuery.isPending.value" state="loading" title="Memuat hasil AI" />
            <StatePanel v-else-if="dispositionReviewQuery.data.value?.review?.status==='PROCESSING'" state="loading" title="AI sedang meninjau arahan dan laporan" />
            <StatePanel v-else-if="dispositionReviewQuery.data.value?.review?.status==='FAILED'" state="error" title="Review AI gagal" description="Coba jalankan review ulang." />
            <div v-else-if="dispositionReviewQuery.data.value?.review?.status==='COMPLETED'" class="mt-4 space-y-3"><div class="rounded-lg bg-violet-50 p-3"><p class="text-[10px] font-bold text-violet-800">Ringkasan AI</p><p class="mt-1 whitespace-pre-line text-xs leading-5 text-slate-700">{{ dispositionReviewQuery.data.value.review.data?.summary || 'Ringkasan tidak tersedia.' }}</p></div><article v-for="recommendation in recommendations" :key="recommendation._id" class="rounded-lg border border-slate-100 p-3"><div class="flex flex-wrap items-start justify-between gap-2"><div><h4 class="text-xs font-bold text-slate-800">{{ recommendation.title }}</h4><p class="mt-1 text-[11px] leading-5 text-slate-600">{{ recommendation.description }}</p><p v-if="recommendation.action" class="mt-1 text-[11px] text-blue-700">Tindakan: {{ recommendation.action }}</p></div><StatusBadge :status="recommendation.status" /></div><div v-if="canManage" class="mt-3 flex flex-wrap gap-2"><BaseButton v-if="recommendation.status==='NEEDS_VERIFICATION'" size="sm" variant="secondary" :disabled="verifyRecommendationMutation.isPending.value" @click="verifyRecommendationMutation.mutate(recommendation)"><ThumbsUp class="size-3.5" />Konfirmasi sumber</BaseButton><template v-if="['PENDING_REVIEW','NEEDS_VERIFICATION'].includes(recommendation.status)"><BaseButton size="sm" :disabled="decisionMutation.isPending.value || recommendation.status==='NEEDS_VERIFICATION'" @click="decisionMutation.mutate({ recommendation, decision: 'approve' })"><ThumbsUp class="size-3.5" />Setujui</BaseButton><BaseButton size="sm" variant="secondary" :disabled="decisionMutation.isPending.value" @click="decisionMutation.mutate({ recommendation, decision: 'reject' })"><ThumbsDown class="size-3.5" />Tolak</BaseButton></template><BaseButton v-if="recommendation.status==='APPROVED' && !followUps.some(item => item.recommendationId===recommendation._id)" size="sm" variant="secondary" @click="openTaskModal(recommendation)"><Plus class="size-3.5" />Masukkan ke tindak lanjut</BaseButton></div></article></div>
          </div>
        </div>
      </PanelCard>

      <PanelCard v-if="memoQuery.data.value?.status==='DISPOSITION_RECEIVED' && canManage" title="Tambah tindak lanjut manual" description="Admin/Pimpinan dapat menambahkan tindakan berdasarkan pengetahuan dan keputusan SPI, termasuk sebelum review disposisi selesai."><form class="grid gap-3 md:grid-cols-2" @submit.prevent="manualMutation.mutate()"><FormField label="Judul tindak lanjut" for-id="manual-title" required><input id="manual-title" v-model="manualForm.title" class="field-input" required /></FormField><FormField label="Prioritas" for-id="manual-priority"><select id="manual-priority" v-model="manualForm.priority" class="field-input"><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></FormField><FormField label="Uraian" for-id="manual-description" required><textarea id="manual-description" v-model="manualForm.description" class="field-input min-h-20" required /></FormField><FormField label="Langkah tindakan" for-id="manual-action"><textarea id="manual-action" v-model="manualForm.action" class="field-input min-h-20" /></FormField><FormField label="Penanggung jawab" for-id="manual-assignee"><select id="manual-assignee" v-model="manualForm.assigneeId" class="field-input"><option value="">Belum ditentukan</option><option v-for="user in assigneesQuery.data.value?.items || []" :key="user._id" :value="user._id">{{ user.name }} · {{ user.unit || 'Unit belum diatur' }}</option></select></FormField><FormField label="Tenggat" for-id="manual-due"><input id="manual-due" v-model="manualForm.dueDate" type="date" class="field-input" /></FormField><div class="flex justify-end md:col-span-2"><BaseButton type="submit" :disabled="manualMutation.isPending.value"><LoaderCircle v-if="manualMutation.isPending.value" class="size-4 animate-spin" /><Plus v-else class="size-4" />Simpan tindak lanjut</BaseButton></div></form></PanelCard>

      <PanelCard v-if="memoQuery.data.value?.reportId" title="Monitoring tindak lanjut" description="Rekomendasi AI yang disetujui dan tindakan manual untuk laporan ini."><StatePanel v-if="followUpsQuery.isPending.value" state="loading" /><StatePanel v-else-if="!followUps.length" state="empty" title="Belum ada tindak lanjut" /><div v-else class="divide-y divide-slate-100"><div v-for="item in followUps" :key="item._id" class="flex flex-wrap items-center justify-between gap-3 py-3"><div><p class="text-xs font-semibold text-slate-800">{{ item.task?.data?.title || 'Tindak lanjut' }}</p><p class="mt-1 text-[10px] text-slate-500">Penanggung jawab: {{ item.assigneeId || 'Belum ditentukan' }} · Tenggat: {{ item.dueDate ? formatDate(item.dueDate) : 'Belum ditentukan' }}</p></div><StatusBadge :status="item.status" /></div></div></PanelCard>
    </section>

    <AppModal :open="modalOpen" title="Buat memo" description="Pilih laporan yang telah selesai direview AI, lalu lengkapi data memo." @close="modalOpen=false"><form class="space-y-3" @submit.prevent="createMemo"><div class="grid gap-3 sm:grid-cols-2"><FormField label="Nomor memo" for-id="memo-number" required><input id="memo-number" v-model="draft.memoNumber" class="field-input" required placeholder="Nomor memo" /></FormField><FormField label="Tanggal memo" for-id="memo-date" required><input id="memo-date" v-model="draft.memoDate" type="date" class="field-input" required /></FormField></div><FormField label="Kepada" for-id="memo-recipient" required><input id="memo-recipient" v-model="draft.recipient" class="field-input" required placeholder="Nama / jabatan penerima" /></FormField><FormField label="Tembusan" for-id="memo-cc" hint="Pisahkan beberapa penerima dengan koma."><input id="memo-cc" v-model="draft.cc" class="field-input" /></FormField><FormField label="Dari unit" for-id="memo-unit" required><input id="memo-unit" v-model="draft.fromUnit" class="field-input" required placeholder="Unit pengirim memo" /></FormField><FormField label="Perihal" for-id="memo-subject" required><input id="memo-subject" v-model="draft.subject" class="field-input" required /></FormField><FormField label="Laporan hasil review AI" for-id="memo-report" required><select id="memo-report" v-model="draft.reportId" class="field-input" required @change="selectReport"><option value="">Pilih laporan</option><option v-for="report in eligibleReports" :key="report._id" :value="report._id">{{ titleOf(report) }} · {{ report._id.slice(-6) }}</option></select></FormField><p v-if="reportsQuery.isError.value" class="text-[11px] text-red-600">Daftar laporan gagal dimuat: {{ getApiErrorMessage(reportsQuery.error.value) }}</p><div class="flex justify-end gap-2 pt-2"><BaseButton variant="secondary" @click="modalOpen=false">Batal</BaseButton><BaseButton type="submit" :disabled="createMutation.isPending.value || !draft.reportReviewId"><LoaderCircle v-if="createMutation.isPending.value" class="size-4 animate-spin" /><FileCheck2 v-else class="size-4" />Simpan memo</BaseButton></div></form></AppModal>
    <AppModal :open="taskModalOpen" title="Jadikan tindak lanjut" description="Tentukan penanggung jawab dan tenggat untuk rekomendasi yang telah disetujui." @close="taskModalOpen=false"><form class="space-y-4" @submit.prevent="createTaskFromRecommendation"><div v-if="taskRecommendation" class="rounded-xl bg-blue-50 p-3"><p class="text-xs font-bold text-blue-900">{{ taskRecommendation.title }}</p><p class="mt-1 text-[11px] text-blue-800">{{ taskRecommendation.action || taskRecommendation.description }}</p></div><FormField label="Penanggung jawab" for-id="recommendation-assignee"><select id="recommendation-assignee" v-model="assignment.assigneeId" class="field-input"><option value="">Belum ditentukan</option><option v-for="user in assigneesQuery.data.value?.items || []" :key="user._id" :value="user._id">{{ user.name }} · {{ user.unit || 'Unit belum diatur' }}</option></select></FormField><FormField label="Tenggat" for-id="recommendation-due"><input id="recommendation-due" v-model="assignment.dueDate" type="date" class="field-input" /></FormField><div class="flex justify-end gap-2"><BaseButton variant="secondary" @click="taskModalOpen=false">Batal</BaseButton><BaseButton type="submit" :disabled="convertMutation.isPending.value"><LoaderCircle v-if="convertMutation.isPending.value" class="size-4 animate-spin" /><Plus v-else class="size-4" />Buat tindak lanjut</BaseButton></div></form></AppModal>
  </main>
</template>
